'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Identity, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './identity.css'

/**
 * Identity: one player, rendered.
 *
 * An avatar, a name, and whatever the host puts beside them. `player-card`,
 * `leaderboard`, `podium`, `versus`, `presence` and `profile` all render a
 * player through this one component, so the avatar cases, the signed-out case
 * and the accessible name are decided once rather than six times.
 *
 * **It renders identity. It never performs authentication.** It makes no
 * network call, reads no cookie, writes no token and talks to no identity
 * provider. The host passes a player or passes null. `data-gs-anonymous` is the
 * host's word that there is no player, never a check this component made, and
 * never a security boundary: a host that hides content behind it has built
 * client-side access control, which this is not.
 *
 * The adapter's `player` is null before sign-in, so signed out is a first-class
 * state with its own rendering and its own test, not a fallback.
 *
 * A player-supplied name is untrusted text. It is rendered as text and never as
 * HTML, and it wraps rather than escaping its row.
 */

/**
 * The shape of `GamestageAdapter.player`, restated here so the component can be
 * installed on its own. A host with a richer player passes the three fields.
 */
export interface IdentityPlayer {
  /** Stable id. Rides `data-gs-player`, so a test can find one row. */
  id: string
  /** What the player calls themselves. Untrusted text. */
  displayName?: string
  /** Where their picture is. The host's URL; this never fetches it itself. */
  avatarUrl?: string
}

export type IdentityPresence = 'online' | 'away' | 'offline'

export type IdentitySize = 'small' | 'default' | 'large'

/** Which of the three avatar cases rendered. See `data-gs-avatar`. */
export type IdentityAvatarCase = 'image' | 'fallback' | 'none'

export interface IdentityProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Who this is. `null` is the signed-out case and renders as one; it is not an
   * error and it is not an empty render.
   */
  player: IdentityPlayer | null
  /** This is the player holding the device. Carries the word "you" in the name. */
  you?: boolean
  /** Whether that player is here now. The host knows; this never asks. */
  presence?: IdentityPresence
  /** Which step of the size scale the avatar and the name render at. */
  size?: IdentitySize
  /**
   * Whether to render an avatar at all. `false` gives `data-gs-avatar="none"`,
   * which is a supported rendering rather than a degraded one: a dense
   * leaderboard row is a legitimate place to want the name alone.
   */
  avatar?: boolean
  /**
   * The name to show, when the host has a better one than `displayName`. Also
   * the way to localise the two defaults below.
   */
  label?: string
  /** Anything the host wants beside the name: a stat, a badge, a control. */
  children?: React.ReactNode
}

/**
 * The words that go with the states, fixed by the attribute contract so that
 * identity, player-card, leaderboard, podium, versus, presence and profile
 * cannot ship seven vocabularies for the same three states.
 */
const STATE_WORD = {
  you: 'you',
  anonymous: 'signed out',
} as const

/** Shown when there is no player, and when a player has no name of their own. */
const DEFAULT_LABEL = { anonymous: 'Guest', unnamed: 'Player' } as const

/**
 * Up to two letters from the name. `Array.from` rather than indexing, because a
 * name beginning with an emoji or any other astral character would otherwise be
 * cut in half and render as a replacement box.
 */
function initials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => Array.from(word)[0] ?? '')
    .join('')
    .toUpperCase()
}

export function Identity({
  player,
  you = false,
  presence,
  size = 'default',
  avatar = true,
  label,
  className,
  children,
  ...rest
}: IdentityProps) {
  // A URL that 404s must not leave a hole where a face was, so a failed image
  // falls back to initials. The failed URL is remembered rather than a boolean,
  // so the next player's picture is attempted rather than inheriting the last
  // one's failure.
  const [failedSrc, setFailedSrc] = React.useState<string | null>(null)

  const anonymous = player === null
  const src = player?.avatarUrl
  const hasImage = avatar && src !== undefined && src !== '' && src !== failedSrc

  const name =
    label ??
    player?.displayName?.trim() ??
    (anonymous ? DEFAULT_LABEL.anonymous : DEFAULT_LABEL.unnamed)
  const shown = name === '' ? DEFAULT_LABEL.unnamed : name

  const avatarCase: IdentityAvatarCase = !avatar ? 'none' : hasImage ? 'image' : 'fallback'

  // The name carries the state, because a screen reader user gets no dot, no
  // colour and no picture. Order matters: who it is, then what is true about
  // them. `data-gs-avatar="none"` adds nothing, deliberately: the player's name
  // is the name, and "no avatar" is not a fact about the player.
  const words = [shown]
  if (you) words.push(STATE_WORD.you)
  if (anonymous) words.push(STATE_WORD.anonymous)
  if (presence) words.push(presence)

  return (
    <div
      {...rest}
      className={['gs-identity', className].filter(Boolean).join(' ')}
      data-gs-component="identity"
      data-gs-player={player?.id}
      data-gs-anonymous={anonymous ? 'true' : undefined}
      data-gs-you={you ? 'true' : undefined}
      data-gs-presence={presence}
      data-gs-avatar={avatarCase}
      data-gs-size={size}
      role="group"
      aria-label={words.join(', ')}
    >
      {/* The avatar is decorative: the name is beside it and the group's label
          above already says who this is, so announcing the picture as well
          would read the same player twice. Hence both an empty alt and
          aria-hidden, and the same treatment on the name and the dot. */}
      {avatarCase === 'none' ? null : (
        <span className="gs-identity__avatar" data-gs-scope="identity" data-gs-part="avatar" aria-hidden="true">
          {avatarCase === 'image' ? (
            <img
              className="gs-identity__image"
              src={src}
              alt=""
              onError={() => setFailedSrc(src ?? null)}
            />
          ) : (
            initials(shown)
          )}
        </span>
      )}
      <span className="gs-identity__text">
        {/* React escapes this. A name is the player's own text and never HTML;
            nothing here reaches dangerouslySetInnerHTML, by construction. */}
        <span className="gs-identity__name" data-gs-scope="identity" data-gs-part="label" aria-hidden="true">
          {shown}
        </span>
        {/* Host content stays announced. It is not part of the group's label,
            so hiding it would silently drop whatever the host put here. */}
        {children === undefined || children === null ? null : (
          <span className="gs-identity__detail" data-gs-scope="identity" data-gs-part="detail">
            {children}
          </span>
        )}
      </span>
      {presence === undefined ? null : (
        // Emphasis, not motion: the dot changes colour and does not move, so
        // its transition survives reduced motion, which is how a player who
        // cannot see motion still sees someone arrive.
        <span
          className="gs-identity__presence"
          data-gs-scope="identity" data-gs-part="presence"
          data-gs-animates="emphasis"
          aria-hidden="true"
        />
      )}
    </div>
  )
}

/* Identity. Every value comes from a token; nothing here is a literal colour. */

.gs-identity {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-3);
  font-family: var(--gs-type-body-font-family);
  color: var(--gs-color-ink);
}

/* -- avatar ---------------------------------------------------------------- */
/* The shape is the theme's, not this file's: arcade sets --gs-shape-identity to
   `circle`, and a border-radius written here would be the one thing a theme
   swap could not reach. The default is the same rounded rectangle every other
   surface uses, so a theme that says nothing still looks like the system. */
.gs-identity__avatar {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--gs-size-icon-object);
  block-size: var(--gs-size-icon-object);
  overflow: hidden;
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-hairline) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);

  /* The initials, when there is no picture. */
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
  text-transform: uppercase;
  user-select: none;
}

/* A style query rather than a value substitution, because the token is a shape
   word and not a length: `border-radius: circle` is invalid and would compute
   to a square corner, silently. */
@container style(--gs-shape-identity: circle) {
  .gs-identity__avatar { border-radius: var(--gs-radius-full); }
}

.gs-identity__image {
  display: block;
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}

/* -- name ------------------------------------------------------------------ */
.gs-identity__text {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
  flex: 1 1 auto;
  min-inline-size: 0;
}

/* A name is the player's own text, so it is arbitrarily long and may have no
   spaces in it at all. It wraps rather than pushing the presence dot, the rank
   or the score out of the row. */
.gs-identity__name {
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  overflow-wrap: anywhere;
}

.gs-identity[data-gs-size='small'] .gs-identity__avatar {
  inline-size: var(--gs-size-icon-control);
  block-size: var(--gs-size-icon-control);
}

.gs-identity[data-gs-size='small'] .gs-identity__name {
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
}

.gs-identity[data-gs-size='large'] .gs-identity__avatar {
  inline-size: var(--gs-size-icon-hero);
  block-size: var(--gs-size-icon-hero);
  font-size: var(--gs-type-stat-font-size);
}

.gs-identity[data-gs-size='large'] .gs-identity__name {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
}

/* -- you ------------------------------------------------------------------- */
/* Colour and weight together, never colour alone: the player's own row has to
   be findable by someone who cannot tell the two colours apart, and the
   accessible name carries the word as well. */
.gs-identity[data-gs-you='true'] .gs-identity__name {
  color: var(--gs-color-player);
  font-weight: var(--gs-type-action-font-weight);
}

/* -- signed out ------------------------------------------------------------ */
/* Quieter than a named player, and still fully legible: this is a real state a
   host renders on purpose, not a broken one. */
.gs-identity[data-gs-anonymous='true'] .gs-identity__name {
  color: var(--gs-color-ink-secondary);
}

/* -- presence -------------------------------------------------------------- */
.gs-identity__presence {
  flex: 0 0 auto;
  inline-size: var(--gs-size-icon-utility);
  block-size: var(--gs-size-icon-utility);
  border-radius: var(--gs-radius-full);
  border: var(--gs-stroke-ui) solid transparent;
  background: var(--gs-color-muted);
  transition: background var(--gs-motion-emphasis) ease-out,
              border-color var(--gs-motion-emphasis) ease-out;
}

.gs-identity[data-gs-presence='online'] .gs-identity__presence {
  background: var(--gs-color-positive);
}

.gs-identity[data-gs-presence='away'] .gs-identity__presence {
  background: var(--gs-color-warning);
}

/* Hollow, not just grey. Filled against ring is a difference in shape, so
   online and offline stay distinguishable without colour vision. */
.gs-identity[data-gs-presence='offline'] .gs-identity__presence {
  background: none;
  border-color: var(--gs-color-muted);
}
